<template>
  <div class="bestiary">
    <div class="header">
      <h1>Bestiary</h1>
    </div>

    <div class="content">
      <!-- Admin Tools -->
      <div v-if="isAdmin" class="admin-wrap">
        <edit-beast :beastToEdit="beastToEdit" @saved="fetchBeasts" />
      </div>

      <div v-if="beasts.length">
        <h2>Beasts</h2>

        <!-- Responsive grid: locked tiles are squares; expanded rows span full width -->
        <ul class="beast-grid">
          <li
            v-for="beast in beasts"
            :key="beast.id"
            class="beast-cell"
            :class="{ 'is-expanded': beast.entryVisible, 'is-expanding': beast.isExpanding }"
          >
            <!-- LOCKED (square) -->
            <div
              v-if="!beast.entryVisible"
              class="restricted-card"
              :class="{ 'is-open': beast.showEntryPrompt }"
              role="button"
              tabindex="0"
              @click="toggleEntryPrompt(beast)"
              @keydown.enter.prevent="toggleEntryPrompt(beast)"
            >
              <div class="restricted-label">RESTRICTED</div>

              <transition name="fade-up">
                <div
                  v-if="beast.showEntryPrompt"
                  class="restricted-controls"
                  @click.stop
                >
                  <input
                    v-model="beast.entryPasswordInput"
                    type="password"
                    placeholder="Enter password to view beast"
                  />
                  <button @click.stop="unlockEntry(beast)">Unlock</button>
                </div>
              </transition>
            </div>

            <!-- EXPANDED (full-width row) -->
            <div v-else class="expanded-row" :class="{ animating: beast.animating }">
              <div class="expand-overlay" :class="{ 'animate': beast.justUnlocked }"></div>

              <!-- Top dossier -->
              <section class="dossier">
