<script>
import { initializeApp } from "firebase/app";
import { getDatabase, ref, get, remove } from "firebase/database";
import Config from '../config';
import EditBeast from './EditBeast.vue';
import { store } from '../scripts/store';
import { setCookie, getCookie } from '../scripts/helperFunctions';

export default {
  name: 'Bestiary',
  components: { EditBeast },
  data() {
    return {
      beasts: [],
      beastToEdit: null,
      db: null,
      isAdmin: store.isAdmin,
      // Scanline travel (matches the photo window height: 188)
      scanlineFrom: 12,
      scanlineTo: 12 + 188
    };
  },
  created() {
    this.app = initializeApp(Config.firebaseConfig);
    this.db = getDatabase(this.app);
    this.fetchBeasts();
    this.isAdmin = store.isAdmin;
  },
  methods: {
    async fetchBeasts() {
      try {
        const snap = await get(ref(this.db, 'bestiary'));
        const data = snap.exists() ? snap.val() : {};

        this.beasts = Object.keys(data).map(id => {
          const cookie = getCookie(id) || '';
          const entryVisible   = cookie.includes('entryVisible')  || !data[id].entryPassword;
          const detailsVisible = cookie.includes('detailsVisible') || false;

          return {
            id,
            ...data[id],
            entryVisible,
            detailsVisible,
            entryPasswordInput: '',
            detailsPasswordInput: '',
            showEntryPrompt: false,
            showDetailsPrompt: false,
            // animation flags
            animating: false,
            isExpanding: false,
            justUnlocked: false,
            staggerIn: false
          };
        });

        // Replay expand animation for already-unlocked rows
        this.$nextTick(() => {
          this.beasts.forEach(b => { if (b.entryVisible) this.animateExpanded(b, { fromMount: true }); });
        });
      } catch (e) {
        console.error('fetchBeasts error:', e);
        this.beasts = [];
      }
    },

    // Admin actions
    editBeast(beast) { this.beastToEdit = { ...beast }; },
    deleteBeast(id) {
      remove(ref(this.db, 'bestiary/' + id))
        .then(() => this.fetchBeasts())
        .catch((e) => console.error('Error deleting beast:', e));
    },

    // UI toggles
    toggleEntryPrompt(beast) { beast.showEntryPrompt = !beast.showEntryPrompt; },
    toggleDetailsPrompt(beast) {
      if (beast.detailsVisible) return;
      beast.showDetailsPrompt = !beast.showDetailsPrompt;
    },

    // Core animation driver (first unlock and on mount)
    animateExpanded(beast, { fromMount = false } = {}) {
      beast.animating = true;
      beast.staggerIn = false;
      beast.justUnlocked = true;
      if (!fromMount) beast.isExpanding = true;

      requestAnimationFrame(() => {
        beast.staggerIn = true;
        setTimeout(() => { beast.justUnlocked = false; }, 650);
        setTimeout(() => {
          beast.animating = false;
          beast.isExpanding = false;
        }, 700);
      });
    },

    // Unlock flows
    unlockEntry(beast) {
      if (beast.entryPasswordInput === beast.entryPassword || !beast.entryPassword) {
        beast.entryVisible = true;
        beast.showEntryPrompt = false;
        setCookie(beast.id, 'entryVisible = true');
        this.$nextTick(() => this.animateExpanded(beast, { fromMount: false }));
      } else {
        alert('Incorrect password!');
      }
    },

    unlockDetails(beast) {
      if (beast.detailsPasswordInput === beast.detailsPassword || !beast.detailsPassword) {
        beast.detailsVisible = true;
        beast.showDetailsPrompt = false; // fades out
        setCookie(beast.id, 'detailsVisible = true');
      } else {
        alert('Incorrect password!');
      }
    }
  }
};
</script>

<style scoped>
