/* Fade-up transition for prompts */
.fade-up-enter-active, .fade-up-leave-active { transition: opacity .25s ease, transform .25s ease; }
.fade-up-enter-from, .fade-up-leave-to { opacity: 0; transform: translateY(6px); }

/* Inputs/Buttons */
button {
  background-color: #b9943d;
