}

/* ---------- Expanded Row ---------- */
.expanded-row {
  position: relative;
  border: 1px solid #b9943d;
  border-radius: 8px;
  padding: 14px;
  background: linear-gradient(180deg, #101521 0%, #0e1118 100%);
  overflow: hidden;
}

/* sweeping overlay that grows left->right */
.expand-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(185,148,61,.18), rgba(185,148,61,.0) 60%);
  transform: scaleX(0);
  transform-origin: left center;
  pointer-events: none;
}
.expand-overlay.animate { animation: sweep .55s ease forwards; }
@keyframes sweep { to { transform: scaleX(1); } }

/* dossier grid */
.dossier {
  display: grid;
  grid-template-columns: 260px 1fr 380px;
  gap: 18px;
}
@media (max-width: 980px) {
