  .dossier { grid-template-columns: 1fr; }
}

/* panel chrome */
.panel { position: relative; border: 1px solid #b9943d5e; background: #111622b0; border-radius: 6px; box-shadow: inset 0 0 0 1px #0b0f17; }

/* STAGGER: visible by default; only hidden while animating */
.fade-step { opacity: 1; transform: none; }
.expanded-row.animating .fade-step { opacity: 0; transform: translateX(-8px); }
.expanded-row.animating .fade-step.in {
  opacity: 1; transform: translateX(0);
  transition: opacity .35s ease, transform .35s ease;
}
.step-1.in { transition-delay: .10s; }
.step-2.in { transition-delay: .22s; }
.step-3.in { transition-delay: .34s; }
.step-4.in { transition-delay: .48s; }

/* ---------- Portrait (SVG) ---------- */
/* outer container for sizing & layout */
.portrait-wrap { width: 100%; aspect-ratio: auto; border: none; padding: 0; background: transparent; display: grid; place-items: center; }
